def parse_float_prefix(s):
    m = re.match(r'[ \t]*([+-]?(?:(?:\d+(?:\.\d*)?)|(?:\.\d+))(?:[eE][+-]?\d+)?)', s)
    if not m:
        return 0.0, 0
    try: return float(m.group(1)), m.end()
    except Exception: return 0.0, 0

def parse_dms_token(tok, angular=True):
    t=tok.strip()
    if not t: return 0.0
    hemi = None
    if t[-1:] in 'NSEWnsew': hemi=t[-1].upper(); t=t[:-1]
    sign = -1 if t.startswith('-') else 1
    if t.startswith(('+','-')): t=t[1:]
    deg=0.0; minute=0.0; sec=0.0
    if 'd' in t or 'D' in t or "'" in t or '"' in t:
        tt=t.replace('D','d')
        if 'd' in tt:
            a,b=tt.split('d',1); deg=float(a) if a else 0.0
        else:
            b=tt
        b=b.replace('"','')
        if "'" in b:
            a,c=b.split("'",1); minute=float(a) if a else 0.0; sec=float(c) if c else 0.0
        elif b:
            minute=float(b)
        val = sign*(deg + minute/60.0 + sec/3600.0)
    else:
        val = sign*float(t)
    if hemi in ('W','S'): val = -abs(val)
    if hemi in ('E','N'): val = abs(val)
    return val

def consume_coord(line, start):
    n=len(line); i=start
    while i<n and line[i] in ' \t': i+=1
    beg=i
    m = re.match(r'[+-]?(?:(?:\d+(?:\.\d*)?)|(?:\.\d+))(?:[eE][+-]?\d+)?', line[i:])
    if not m:
        return 0.0, start, ''
    i += m.end()
    while i<n and line[i] not in ' \t\r\n,:' and line[i] in "dD'\"NSEWnsew0123456789.+-":
        i += 1
    tok=line[beg:i]
    try: val=parse_dms_token(tok)
    except Exception:
        val=0.0
    return val, i, tok

def parse_line(line, reverse_input=False):
    raw=line.rstrip('\n')
    if raw.startswith('#'):
        return None
    x, pos, tok1 = consume_coord(raw, 0)
    y=0.0; tok2=''; rest=raw[pos:]
    if pos < len(raw) and raw[pos] in ' \t':
        y, pos2, tok2 = consume_coord(raw, pos)
        pos=pos2; rest=raw[pos:]
    if reverse_input: x,y=y,x; tok1,tok2=tok2,tok1
    if tok2:
        echo = raw[:pos]
    elif tok1:
        echo = tok1
    else:
        echo = ''
    return x,y,rest,echo,raw

def fmt_num(x, fmt):
    if math.isnan(x) or math.isinf(x): return '*'
    try:
        return fmt % x
    except Exception:
        return ("%.2f" % x)

def dms_format(deg, kind='lon', mode='compact', sec_digits=0):
    hemi = 'E' if kind=='lon' else 'N'
    if deg < 0: hemi = 'W' if kind=='lon' else 'S'
    v=abs(deg)
    if mode=='full':
        d=int(math.floor(v+1e-12)); rem=(v-d)*60; m=int(math.floor(rem+1e-12)); s=(rem-m)*60
        s=round(s, sec_digits)
        if s >= 60.0: s-=60.0; m+=1
        if m >= 60: m-=60; d+=1
        width=3+sec_digits if sec_digits else 2
        return f"{d}d{m:02d}'{s:0{width}.{sec_digits}f}\"{hemi}"
    total_sec = round(v*3600.0, 9)
    d=int(total_sec//3600); total_sec-=d*3600
    m=int(total_sec//60); s=total_sec-m*60
    if abs(s) < 5e-10 and m==0: return f"{d}d{hemi}"
    if abs(s) < 5e-10: return f"{d}d{m}'{hemi}"
    ss=("%.3f" % s).rstrip('0').rstrip('.')
    return f"{d}d{m}'{ss}\"{hemi}"

def meridional_coeffs(e2):
    e4=e2*e2; e6=e4*e2; e8=e4*e4
