            3*e2/8 + 3*e4/32 + 45*e6/1024 + 105*e8/4096,
            15*e4/256 + 45*e6/1024 + 525*e8/16384,
            35*e6/3072 + 175*e8/12288,
            315*e8/131072)

def meridional_arc(a,e2,phi):
    c=meridional_coeffs(e2)
    return a*(c[0]*phi - c[1]*math.sin(2*phi) + c[2]*math.sin(4*phi) - c[3]*math.sin(6*phi) + c[4]*math.sin(8*phi))

def inv_meridional_arc(a,e2,M):
    phi=M/(a*(1-e2/4-3*e2*e2/64-5*e2**3/256))
    for _ in range(12):
        s=math.sin(phi)
        rho=a*(1-e2)/((1-e2*s*s)**1.5)
        phi -= (meridional_arc(a,e2,phi)-M)/rho
