def msfn(e2,phi):
    return math.cos(phi)/math.sqrt(1-e2*math.sin(phi)**2)

def tsfn(e,phi):
    s=math.sin(phi)
    return math.tan(math.pi/4 - phi/2) / (((1-e*s)/(1+e*s))**(e/2)) if e else math.tan(math.pi/4-phi/2)

def phi2_from_t(e,t):
    phi=math.pi/2-2*math.atan(t)
    for _ in range(15):
        es=e*math.sin(phi)
        new=math.pi/2 - 2*math.atan(t*((1-es)/(1+es))**(e/2))
        if abs(new-phi)<1e-14: break
