    return phi

def qsfn(e,e2,phi):
    s=math.sin(phi)
    if e < 1e-15: return 2*s
    return (1-e2)*(s/(1-e2*s*s) - (1/(2*e))*math.log((1-e*s)/(1+e*s)))

def authalic_radius(a,e,e2):
    qp=qsfn(e,e2,math.pi/2)
    return a*math.sqrt(0.5*qp)

def auth_lat(e,e2,phi):
    qp=qsfn(e,e2,math.pi/2)
    q=qsfn(e,e2,phi)
    v=max(-1,min(1,q/qp))
    return math.asin(v)

def is_float(s):
    try: float(s); return True
    except Exception: return False

def opt_angle(opts,k,default):
    return parse_dms_token(str(opts[k])) if k in opts else default

def rad(d): return d*math.pi/180.0
def deg(r): return r*180.0/math.pi

