        else: phi=phi2_from_t(e, math.exp(-yy))
    elif p=='eqc':
        lam=P.lon0+(x-P.x0)/(a*P.k0)
        if P.sphere: phi=P.lat0+(y-P.y0)/(a*P.k0)
        else: phi=inv_meridional_arc(a,e2,(y-P.y0)+meridional_arc(a,e2,P.lat0))
