def parse_args(argv):
    flags={'inverse':False,'echo':False,'rev_in':False,'rev_out':False,'verbose':0,'stats':False}
    fmt='%.2f'; angular_fmt=None; w_mode='compact'; w_digits=0; mult=1.0; errstr='*'
    opts={}; files=[]; list_req=None
    i=0
    while i < len(argv):
        arg=argv[i]
        if arg.startswith('+'):
            s=arg[1:]
            if '=' in s: k,v=s.split('=',1); opts[k]=v
            else: opts[s]=True
        elif arg.startswith('-') and arg!='-':
            if arg.startswith('--'): die('invalid option: --')
            # special -l=foo
            if arg.startswith('-l'):
                list_req=arg[2:] if len(arg)>2 else 'p'; i+=1; continue
            j=1
            while j < len(arg):
                c=arg[j]
                if c=='I': flags['inverse']=True; j+=1
                elif c=='E': flags['echo']=True; j+=1
                elif c=='r': flags['rev_in']=True; j+=1
                elif c=='s': flags['rev_out']=True; j+=1
                elif c=='S': flags['stats']=True; j+=1
                elif c=='v': flags['verbose']=max(flags['verbose'],1); j+=1
                elif c=='V': flags['verbose']=max(flags['verbose'],2); j+=1
                elif c in 'bcdiotTwWefm':
                    val=None
                    if j+1 < len(arg): val=arg[j+1:]; j=len(arg)
                    else:
                        if i+1 < len(argv): val=argv[i+1]; i+=1
                        else: die(f'-{c} argument missing')
                        j=len(arg)
                    if c=='f': fmt=val; angular_fmt=val
                    elif c=='d':
                        try: n=int(val); fmt='%.'+str(n)+'f'; angular_fmt=fmt
                        except Exception: pass
                    elif c=='e': errstr=val
                    elif c=='m':
                        try: mult=float(val)
                        except Exception: mult=1.0
                    elif c=='W':
                        if val is None or not val.isdigit(): die('-W argument missing or non-digit')
                        w_mode='full'; w_digits=int(val)
                    elif c=='w':
                        if val is None or not val.isdigit(): die('-W argument missing or non-digit')
                        w_mode='compact'; w_digits=int(val)
                else:
                    die(f'invalid option: -{c}')
        else:
            files.append(arg)
        i+=1
    if list_req is not None:
        return {'list':list_req, 'opts':opts}
    return {'flags':flags,'fmt':fmt,'angular_fmt':angular_fmt,'w_mode':w_mode,'w_digits':w_digits,'mult':mult,'errstr':errstr,'opts':opts,'files':files}

def do_list(req):
    if req in ('p',''):
        sys.stdout.write(PROJ_LIST); return 0
    if req=='P': sys.stdout.write(PROJ_DETAIL); return 0
    if req=='e': sys.stdout.write(ELLPS_LIST); return 0
    if req=='u': sys.stdout.write(UNITS_LIST); return 0
    if req.startswith('='):
        name=req[1:]
        if name in DETAIL_LINES:
            first=DETAIL_LINES[name][0]
            sys.stdout.write(f"{name:>9} : "+first.split(' : ',1)[1]+"\n")
            for l in DETAIL_LINES[name][1:]: sys.stdout.write(l+"\n")
        elif name in PROJ_NAMES:
            sys.stdout.write(f"{name:>9} : {PROJ_NAMES[name]}\n")
        return 0
    die('invalid list option: l'+req)

def header(P, level):
