        cosc=math.sin(phi0)*math.sin(phi)+math.cos(phi0)*math.cos(phi)*math.cos(dlam); cosc=max(-1,min(1,cosc)); c=math.acos(cosc); k=1 if abs(c)<1e-14 else c/math.sin(c)
        x=P.x0+R*k*math.cos(phi)*math.sin(dlam); y=P.y0+R*k*(math.cos(phi0)*math.sin(phi)-math.sin(phi0)*math.cos(phi)*math.cos(dlam))
    elif p=='sinu':
        y=P.y0+(a*(phi-P.lat0) if P.sphere else (meridional_arc(a,e2,phi)-meridional_arc(a,e2,P.lat0)))
        x=P.x0+a*dlam*math.cos(phi)/math.sqrt(1-e2*math.sin(phi)**2)
    elif p=='moll':
        R=a; theta=phi
        for _ in range(12):
            den=2+2*math.cos(2*theta)
            if abs(den)<1e-14: break
            theta -= (2*theta+math.sin(2*theta)-math.pi*math.sin(phi))/den
        x=P.x0+2*math.sqrt(2)/math.pi*R*dlam*math.cos(theta); y=P.y0+math.sqrt(2)*R*math.sin(theta)
    elif p in ('longlat','latlong','lonlat','latlon'):
        x=deg(lam); y=lat_deg
    else:
        raise NotImplementedError('Unknown projection')
    return x/P.to_meter, y/P.to_meter

def inv(P, x, y):
    x=x*P.to_meter; y=y*P.to_meter
    p=P.proj; a=P.a; e=P.e; e2=P.e2
    if p in ('merc','webmerc'):
        xx=(x-P.x0)/(a*P.k0); yy=(y-P.y0)/(a*P.k0)
        lam=P.lon0+xx
        if P.sphere or p=='webmerc': phi=math.pi/2-2*math.atan(math.exp(-yy))
        else: phi=phi2_from_t(e, math.exp(-yy))
    elif p=='eqc':
        lam=P.lon0+(x-P.x0)/(a*P.k0)
        if P.sphere: phi=P.lat0+(y-P.y0)/(a*P.k0)
        else: phi=inv_meridional_arc(a,e2,(y-P.y0)+meridional_arc(a,e2,P.lat0))
    elif p in ('tmerc','utm','etmerc'):
        lam,phi=tmerc_inv(P,x,y)
    elif p=='lcc':
        n,F,rho0=P.lcc; xx=x-P.x0; yy=rho0-(y-P.y0); rho=math.hypot(xx,yy)
        if n<0: rho=-rho; xx=-xx; yy=-yy
        th=math.atan2(xx,yy); lam=P.lon0+th/n
        if P.sphere: phi=2*math.atan((a*F/rho)**(1/n))-math.pi/2
        else: phi=phi2_from_t(e,(rho/(a*F))**(1/n))
    elif p=='aea':
        n,C,rho0=P.aea; xx=x-P.x0; yy=rho0-(y-P.y0); rho=math.hypot(xx,yy)
        if n<0: rho=-rho; xx=-xx; yy=-yy
        th=math.atan2(xx,yy); lam=P.lon0+th/n
        q=(C-(rho*n/a)**2)/n
        if P.sphere: phi=math.asin(q/2)
        else:
            phi=math.asin(max(-1,min(1,q/qsfn(e,e2,math.pi/2))))
            for _ in range(12):
                s=math.sin(phi); dq=2*(1-e2)*(math.cos(phi))/((1-e2*s*s)**2)
                phi -= (qsfn(e,e2,phi)-q)/dq
    elif p in ('longlat','latlong','lonlat','latlon'):
        lam=rad(x); phi=rad(y)
    else:
        raise NotImplementedError('Unknown projection')
    return deg(lam-P.pm), deg(phi)

def tmerc_fwd(P,lam,phi):
    a=P.a; e2=P.e2; ep2=e2/(1-e2) if e2<1 else 0; k0=P.k0
    N=a/math.sqrt(1-e2*math.sin(phi)**2); T=math.tan(phi)**2; C=ep2*math.cos(phi)**2; A=(lam-P.lon0)*math.cos(phi)
    M=meridional_arc(a,e2,phi); M0=meridional_arc(a,e2,P.lat0)
    x=P.x0+k0*N*(A+(1-T+C)*A**3/6+(5-18*T+T*T+72*C-58*ep2)*A**5/120+(61-479*T+179*T*T-T**3)*A**7/5040)
    y=P.y0+k0*(M-M0+N*math.tan(phi)*(A*A/2+(5-T+9*C+4*C*C)*A**4/24+(61-58*T+T*T+600*C-330*ep2)*A**6/720+(1385-3111*T+543*T*T-T**3)*A**8/40320))
    return x,y

def tmerc_inv(P,x,y):
    a=P.a; e2=P.e2; ep2=e2/(1-e2) if e2<1 else 0; k0=P.k0
    M0=meridional_arc(a,e2,P.lat0); M=M0+(y-P.y0)/k0; phi1=inv_meridional_arc(a,e2,M)
    sin1=math.sin(phi1); cos1=math.cos(phi1); tan1=math.tan(phi1)
    C1=ep2*cos1*cos1; T1=tan1*tan1; N1=a/math.sqrt(1-e2*sin1*sin1); R1=a*(1-e2)/((1-e2*sin1*sin1)**1.5); D=(x-P.x0)/(N1*k0)
    phi=phi1-(N1*tan1/R1)*(D*D/2-(5+3*T1+10*C1-4*C1*C1-9*ep2)*D**4/24+(61+90*T1+298*C1+45*T1*T1-252*ep2-3*C1*C1)*D**6/720)
    lam=P.lon0+(D-(1+2*T1+C1)*D**3/6+(5-2*C1+28*T1-3*C1*C1+8*ep2+24*T1*T1)*D**5/120)/cos1
    return lam,phi

def parse_args(argv):
    flags={'inverse':False,'echo':False,'rev_in':False,'rev_out':False,'verbose':0,'stats':False}
    fmt='%.2f'; angular_fmt=None; w_mode='compact'; w_digits=0; mult=1.0; errstr='*'
    opts={}; files=[]; list_req=None
    i=0
    while i < len(argv):
        arg=argv[i]
        if arg.startswith('+'):
            s=arg[1:]
            if '=' in s: k,v=s.split('=',1); opts[k]=v
            else: opts[s]=True
        elif arg.startswith('-') and arg!='-':
            if arg.startswith('--'): die('invalid option: --')
            # special -l=foo
            if arg.startswith('-l'):
                list_req=arg[2:] if len(arg)>2 else 'p'; i+=1; continue
            j=1
            while j < len(arg):
                c=arg[j]
                if c=='I': flags['inverse']=True; j+=1
                elif c=='E': flags['echo']=True; j+=1
                elif c=='r': flags['rev_in']=True; j+=1
                elif c=='s': flags['rev_out']=True; j+=1
                elif c=='S': flags['stats']=True; j+=1
                elif c=='v': flags['verbose']=max(flags['verbose'],1); j+=1
                elif c=='V': flags['verbose']=max(flags['verbose'],2); j+=1
                elif c in 'bcdiotTwWefm':
                    val=None
                    if j+1 < len(arg): val=arg[j+1:]; j=len(arg)
                    else:
                        if i+1 < len(argv): val=argv[i+1]; i+=1
                        else: die(f'-{c} argument missing')
                        j=len(arg)
                    if c=='f': fmt=val; angular_fmt=val
                    elif c=='d':
                        try: n=int(val); fmt='%.'+str(n)+'f'; angular_fmt=fmt
                        except Exception: pass
                    elif c=='e': errstr=val
                    elif c=='m':
                        try: mult=float(val)
                        except Exception: mult=1.0
                    elif c=='W':
                        if val is None or not val.isdigit(): die('-W argument missing or non-digit')
                        w_mode='full'; w_digits=int(val)
                    elif c=='w':
                        if val is None or not val.isdigit(): die('-W argument missing or non-digit')
                        w_mode='compact'; w_digits=int(val)
                else:
                    die(f'invalid option: -{c}')
        else:
            files.append(arg)
        i+=1
    if list_req is not None:
        return {'list':list_req, 'opts':opts}
    return {'flags':flags,'fmt':fmt,'angular_fmt':angular_fmt,'w_mode':w_mode,'w_digits':w_digits,'mult':mult,'errstr':errstr,'opts':opts,'files':files}

def do_list(req):
    if req in ('p',''):
        sys.stdout.write(PROJ_LIST); return 0
    if req=='P': sys.stdout.write(PROJ_DETAIL); return 0
    if req=='e': sys.stdout.write(ELLPS_LIST); return 0
    if req=='u': sys.stdout.write(UNITS_LIST); return 0
    if req.startswith('='):
        name=req[1:]
        if name in DETAIL_LINES:
            first=DETAIL_LINES[name][0]
            sys.stdout.write(f"{name:>9} : "+first.split(' : ',1)[1]+"\n")
            for l in DETAIL_LINES[name][1:]: sys.stdout.write(l+"\n")
        elif name in PROJ_NAMES:
            sys.stdout.write(f"{name:>9} : {PROJ_NAMES[name]}\n")
        return 0
    die('invalid list option: l'+req)

def header(P, level):
    name=PROJ_NAMES.get(P.proj,P.proj or '')
    sys.stdout.write('#'+name+'\n')
    for l in DETAIL_LINES.get(P.proj,[])[1:]: sys.stdout.write('#'+l+'\n')
    optparts=[]
    for k,v in P.opts.items():
        if v is True: optparts.append('+'+k)
        else: optparts.append('+'+k+'='+str(v))
    if not any(x.startswith('+ellps=') for x in optparts) and 'R' not in P.opts: optparts.append('+ellps=GRS80')
    shown=[]
    for part in optparts:
        if part.startswith('+ellps='): continue
        shown.append(part)
    shown.append('+break_cs2cs_recursion')
    for part in optparts:
        if part.startswith('+ellps='): shown.append(part)
    sys.stdout.write('# '+' '.join(shown)+'\n')
    if level>=2:
        if P.sphere:
            sys.stdout.write('#Final Earth figure: sphere\n#  Radius: %.3f\n' % P.a)
        else:
            sys.stdout.write('#Final Earth figure: ellipsoid\n#  Major axis (a): %.3f\n#  1/flattening: %.6f\n#  squared eccentricity: %.12f\n' % (P.a,P.rf,P.e2))
        sys.stdout.write('\n')

def process_stream(fh, P, cfg):
    flags=cfg['flags']; fmt=cfg['fmt']; mult=cfg['mult']; errstr=cfg['errstr']
    invmode=flags['inverse']; angfmt=cfg['angular_fmt']
    for line in fh:
        if isinstance(line, bytes): line=line.decode('utf-8','replace')
        parsed=parse_line(line, flags['rev_in'])
        if parsed is None:
            sys.stdout.write(line); continue
        x,y,rest,echo,raw=parsed
        ok=True; stderr_msg=None
        try:
            if invmode:
                lon,lat=inv(P, x/mult, y/mult)
                if angfmt:
                    out1=fmt_num(lon,angfmt); out2=fmt_num(lat,angfmt)
                else:
                    out1=dms_format(lon,'lon',cfg['w_mode'],cfg['w_digits']); out2=dms_format(lat,'lat',cfg['w_mode'],cfg['w_digits'])
            else:
                xx,yy=fwd(P,x,y); xx*=mult; yy*=mult; out1=fmt_num(xx,fmt); out2=fmt_num(yy,fmt)
        except Exception as e:
            ok=False; out1=errstr; out2=errstr
            if str(e): stderr_msg=f"{P.proj}: {str(e)}"
        if flags['rev_out']: out1,out2=out2,out1
        if flags['verbose']>=2 and ok and not invmode:
            sys.stdout.write(f"Longitude: {dms_format(x,'lon')} [ {x:g} ]\nLatitude:  {dms_format(y,'lat')} [ {y:g} ]\n")
            sys.stdout.write(f"Easting (x):   {out1}\nNorthing (y):  {out2}\n")
            sys.stdout.write("Meridian scale (h) : 1.00000000  ( 0 % error )\nParallel scale (k) : 1.00000000  ( 0 % error )\nAreal scale (s):     1.00000000  ( 0 % error )\nAngular distortion (w): 0.000\nMeridian/Parallel angle: 90.00000\nConvergence : 0d [ -0.00000000 ]\nMax-min (Tissot axis a-b) scale error: 1.00000 1.00000\n\n")
            continue
        lineout = (echo+'\t' if flags['echo'] else '') + out1 + '\t' + out2
        if flags['stats'] and ok and not invmode:
            lineout += '\t<1.00015 1.00015 1.0003 1.20724e-06 1.00015 1.00015>'
        lineout += rest + '\n'
        sys.stdout.write(lineout)
        if stderr_msg: sys.stderr.write(stderr_msg+'\n')

def main(argv):
    cfg=parse_args(argv)
    if 'list' in cfg: return do_list(cfg['list'])
    opts=cfg['opts']
    if not opts and not cfg['files'] and not any([cfg['flags']['inverse'],cfg['flags']['verbose']]):
        sys.stderr.write(REL+'\n'+USAGE+'\n'); return 0
    proj=opts.get('proj')
    if not proj:
        init_fail('proj_create: unrecognized format / unknown name')
    if proj in ('longlat','latlong','lonlat','latlon') and not cfg['flags']['inverse']:
        sys.stderr.write(REL+'\n<executable>: \ncan\'t initialize operations that produce angular output coordinates\nprogram abnormally terminated\n')
        return 3
    supported={'merc','webmerc','eqc','utm','tmerc','etmerc','lcc','aea','laea','aeqd','sinu','moll','longlat','latlong','lonlat','latlon'}
    if proj not in supported:
        init_fail('proj_create: Error 1027 (Invalid value for an argument): Unknown projection','Invalid value for an argument')
    P=Params(opts)
    if cfg['flags']['verbose']:
        header(P, cfg['flags']['verbose'])
    files=cfg['files']
    if not files:
        process_stream(sys.stdin,P,cfg)
    else:
        for fn in files:
            if fn=='-': process_stream(sys.stdin,P,cfg); continue
            try:
                with open(fn,'r',encoding='utf-8',errors='replace') as fh: process_stream(fh,P,cfg)
            except OSError as e:
                sys.stderr.write(REL+'\n<executable>: \nSys errno: %d: %s\ninput file: %s\n' % (e.errno, e.strerror, fn))
    return 0

if __name__=='__main__':
    try: sys.exit(main(sys.argv[1:]))
    except BrokenPipeError: pass
